draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // draw celery
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 50, H/2 + 20 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 30, H/2 + 60);
  ctx.lineTo(W/2 - 30, H/2 + 60);
  ctx.lineTo(W/2 - 50, H/2 + 20 + 20 * Math.sin(t));
  ctx.closePath();
  ctx.stroke();
  ctx.fill();

  // draw stick figure eating
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 80, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 120, H/2);
  ctx.stroke();

  // draw text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Crunchy', W/2, H/2 + 100);
  ctx.fillText('Low Calorie', W/2, H/2 + 130);

  ctx.restore();
}
